//! Reusable CLI socket connection adapter. Caller owns listener and authorizes all I/O.
use super::{csdm_analysis::Analyses,csdm_analysis_service as svc,cli_handler};
use serde_json::{json,Value};
use std::{collections::HashMap,io,net::TcpStream,sync::{Arc,Mutex,mpsc::{self,SyncSender,TrySendError},atomic::{AtomicU64,AtomicBool,Ordering}},thread,time::{Duration,Instant}};
fn lock_until<'a,T>(m:&'a Mutex<T>,deadline:Instant,label:&str)->Result<std::sync::MutexGuard<'a,T>,String>{loop{if Instant::now()>=deadline{return Err(format!("{label} shutdown unconfirmed"))}match m.try_lock(){Ok(g)=>return Ok(g),Err(std::sync::TryLockError::Poisoned(_))=>return Err(format!("{label} poisoned; shutdown unconfirmed")),Err(std::sync::TryLockError::WouldBlock)=>thread::sleep(Duration::from_millis(5))}}}
type Prepare=dyn Fn(Value,&AtomicBool)->Result<(Value,Vec<Value>),String>+Send+Sync;
type Notify=dyn Fn()->Result<(),String>+Send+Sync;
type Renderer=dyn Fn(Value)->Result<(),String>+Send+Sync;
struct Outbound{value:Value,ack:Option<SyncSender<Result<(),String>>>}
static NEXT_ID:AtomicU64=AtomicU64::new(0);
pub struct Hub{state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,prepare:Arc<Prepare>,wake:Arc<Notify>,renderer_tx:Mutex<Option<SyncSender<Outbound>>>,renderer_worker:Mutex<Option<thread::JoinHandle<()>>>,peers:Mutex<HashMap<String,SyncSender<Outbound>>>,issues:Arc<Mutex<Vec<String>>>,issues_lost:AtomicBool,renderer_terminal:Mutex<Option<String>>,request_workers:Mutex<Vec<thread::JoinHandle<()>>>,request_terminal:Mutex<Option<String>>,stopping:AtomicBool,renderer_admission:Mutex<()>,#[cfg(test)] test_admitted:AtomicBool}
impl Hub{
 pub fn new(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,resolve:impl Fn(Value)->Result<Vec<Value>,String>+Send+Sync+'static)->Self{Self::from_parts(state,order,move |payload,_|{let demos=resolve(payload)?;let added:Vec<Value>=demos.iter().map(|d|json!({"checksum":d["checksum"],"demoPath":d["filePath"]})).collect();Ok((json!({"addedDemos":added,"skippedDemoPaths":[],"unsupportedDemos":[]}),demos))},||Ok(()),|_|Ok(()))}
 pub fn from_parts(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,prepare:impl Fn(Value,&AtomicBool)->Result<(Value,Vec<Value>),String>+Send+Sync+'static,wake:impl Fn()->Result<(),String>+Send+Sync+'static,renderer:impl Fn(Value)->Result<(),String>+Send+Sync+'static)->Self{{let(tx,rx)=mpsc::sync_channel::<Outbound>(64);let issues=Arc::new(Mutex::new(Vec::new()));let report=issues.clone();let worker=thread::spawn(move||{while let Ok(out)=rx.recv(){let result=renderer(out.value);if let Err(error)=&result{if let Ok(mut log)=report.lock(){log.push(format!("renderer push failed: {error}"))}}if let Some(ack)=out.ack{let _=ack.send(result);}}});Self{state,order,prepare:Arc::new(prepare),wake:Arc::new(wake),renderer_tx:Mutex::new(Some(tx)),renderer_worker:Mutex::new(Some(worker)),peers:Mutex::new(HashMap::new()),issues,issues_lost:AtomicBool::new(false),renderer_terminal:Mutex::new(None),request_workers:Mutex::new(Vec::new()),request_terminal:Mutex::new(None),stopping:AtomicBool::new(false),renderer_admission:Mutex::new(()),#[cfg(test)] test_admitted:AtomicBool::new(false)}}}
 pub fn from_handler(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,checksums:impl Fn(&AtomicBool)->Result<Vec<String>,String>+Send+Sync+'static,resolve:impl Fn(&str,&AtomicBool)->Result<Value,String>+Send+Sync+'static,wake:super::scheduler_owner::Wake,renderer:impl Fn(Value)->Result<(),String>+Send+Sync+'static)->Self{Self::from_parts(state,order,move |payload,cancel|{let known=checksums(cancel)?;cli_handler::prepare_cli(&payload,&known,|path|resolve(path,cancel))},move||wake.wake(),renderer)}
 pub(super) fn record_issue(&self,message:String){if let Ok(mut errors)=self.issues.lock(){errors.push(message)}else{self.issues_lost.store(true,Ordering::Release)}}
 #[cfg(test)] pub(super) fn test_track_request(&self,worker:thread::JoinHandle<()>){self.request_workers.lock().unwrap().push(worker)}
 pub fn request_workers_quiescent(&self)->Result<bool,String>{self.request_workers.lock().map(|v|v.is_empty()).map_err(|_|"request worker tracking unavailable".into())}
 pub fn join_request_workers(&self,timeout:Duration)->Result<(),String>{let mut workers=self.request_workers.lock().map_err(|_|"request worker tracking unavailable")?;let end=Instant::now()+timeout;while workers.iter().any(|w|!w.is_finished())&&Instant::now()<end{thread::sleep(Duration::from_millis(10))}let mut pending=Vec::new();let mut failed=false;for worker in workers.drain(..){if worker.is_finished(){if worker.join().is_err(){failed=true}}else{pending.push(worker)}}*workers=pending;if failed{*self.request_terminal.lock().map_err(|_|"request terminal state unavailable")?=Some("request worker panicked".into())}if let Some(error)=self.request_terminal.lock().map_err(|_|"request terminal state unavailable")?.clone(){return Err(error)}if !workers.is_empty(){return Err("request worker shutdown unconfirmed".into())}Ok(())}
 pub fn peer_count(&self)->Result<usize,String>{self.peers.lock().map(|p|p.len()).map_err(|_|"CLI peer registry unavailable".into())}
 pub fn renderer_add(&self,demos:Vec<Value>)->Result<(),String>{let _guard=self.renderer_admission.lock().map_err(|_|"renderer admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("service stopping".into())}#[cfg(test)] self.test_admitted.store(true,Ordering::Release);let added=svc::ordered(&self.state,&self.order,|s|{let event=s.add(demos,None,None,||chrono::DateTime::<chrono::Utc>::from(std::time::SystemTime::now()).to_rfc3339_opts(chrono::SecondsFormat::Millis,true))?;Ok((event.is_some(),event))},&mut |e|self.publish(e))?;if added{if let Err(error)=(self.wake)(){self.record_issue(format!("scheduler wake failed after renderer enqueue: {error}"))}}Ok(())}
 pub fn renderer_remove(&self,keys:Vec<String>)->Result<(),String>{let _guard=self.renderer_admission.lock().map_err(|_|"renderer admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("service stopping".into())}svc::ordered(&self.state,&self.order,|s|{let refs:Vec<&str>=keys.iter().map(String::as_str).collect();s.remove(&refs);Ok(((),Some(json!({"name":"demos-removed-from-analyses","payload":keys}))))},&mut |e|self.publish(e))}
 #[cfg(test)] pub(super) fn test_renderer_admitted(&self)->bool{self.test_admitted.load(Ordering::Acquire)}
 #[cfg(test)] pub(super) fn test_admission_locked(&self)->bool{self.renderer_admission.try_lock().is_err()}
 pub fn stop_admission(&self,timeout:Duration)->Result<(),String>{self.stopping.store(true,Ordering::Release);let deadline=Instant::now()+timeout;let _guard=lock_until(&self.renderer_admission,deadline,"renderer admission")?;Ok(())}
 pub fn wake_owner(&self)->Result<(),String>{(self.wake)()}
 pub fn reconcile_closed(&self)->Result<(),String>{let clients=self.state.lock().map_err(|_|"Analysis state unavailable")?.closed_clients();for id in clients{svc::cli_disconnected(&self.state,&self.order,&id,&mut |e|self.publish(e))?;self.state.lock().map_err(|_|"Analysis state unavailable")?.forget_client(&id);}Ok(())}
 pub fn shutdown_renderer(&self,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;lock_until(&self.renderer_tx,deadline,"renderer queue")?.take();let mut slot=lock_until(&self.renderer_worker,deadline,"renderer worker")?;let mut terminal=lock_until(&self.renderer_terminal,deadline,"renderer terminal")?;if let Some(error)=terminal.clone(){return Err(error)}let Some(worker)=slot.as_ref()else{return Ok(())};while !worker.is_finished(){if Instant::now()>=deadline{return Err("renderer worker shutdown unconfirmed".into())}thread::sleep(Duration::from_millis(5))}if slot.take().unwrap().join().is_err(){let error="renderer worker panicked".to_string();*terminal=Some(error.clone());return Err(error)}Ok(())}
 pub fn delivery_issues_until(&self,timeout:Duration)->Result<Vec<String>,String>{if self.issues_lost.load(Ordering::Acquire){return Err("CLI delivery diagnostics lost".into())}Ok(lock_until(&self.issues,Instant::now()+timeout,"delivery diagnostics")?.clone())}
 pub fn delivery_issues(&self)->Result<Vec<String>,String>{if self.issues_lost.load(Ordering::Acquire){return Err("CLI delivery diagnostics lost".into())}self.issues.lock().map(|v|v.clone()).map_err(|_|"CLI delivery diagnostics unavailable".into())}
 pub(super) fn publish_peers_confirmed(&self,event:&Value,timeout:Duration)->Result<(),String>{
  let deadline=Instant::now()+timeout;let peers:Vec<SyncSender<Outbound>>=lock_until(&self.peers,deadline,"CLI settings push")?.values().cloned().collect();
  for tx in peers {let(ack,rx)=mpsc::sync_channel(1);tx.try_send(Outbound{value:event.clone(),ack:Some(ack)}).map_err(|e|format!("CLI settings push not queued: {e}"))?;let remaining=deadline.saturating_duration_since(Instant::now());if remaining.is_zero(){return Err("CLI settings push outcome unconfirmed".into())}rx.recv_timeout(remaining).map_err(|e|format!("CLI settings push outcome unconfirmed: {e}"))??;}
  Ok(())
 }
 /// Queue each destination independently and await the renderer emitter. Socket queueing is not delivery.
 pub(super) fn queue_settings(&self,event:Value,timeout:Duration)->Result<(),String>{
  let deadline=Instant::now()+timeout;let mut errors=Vec::new();let (ack_tx,ack_rx)=mpsc::sync_channel(1);let mut queued=false;
  match self.peers.try_lock().map_err(|_|"CLI settings queue unavailable".to_string()) {Ok(peers)=>for tx in peers.values(){if let Err(e)=tx.try_send(Outbound{value:event.clone(),ack:None}){errors.push(format!("CLI settings not queued: {e}"))}},Err(e)=>errors.push(e)}
  match self.renderer_tx.try_lock().map_err(|_|"renderer settings queue unavailable".to_string()) {Ok(slot)=>match slot.as_ref(){Some(tx)=>match tx.try_send(Outbound{value:event,ack:Some(ack_tx)}){Ok(())=>queued=true,Err(e)=>errors.push(format!("renderer settings not queued: {e}"))},None=>errors.push("renderer stopped".into())},Err(e)=>errors.push(e)}
  if queued {match ack_rx.recv_timeout(deadline.saturating_duration_since(Instant::now())){Ok(Ok(()))=>(),Ok(Err(e))=>errors.push(format!("renderer settings emit failed: {e}")),Err(e)=>errors.push(format!("renderer settings outcome unconfirmed: {e}"))}}
  if errors.is_empty(){Ok(())}else{Err(errors.join("; "))}
 }
 pub(super) fn publish(&self,event:Value)->Result<(),String>{{let peers=self.peers.lock().map_err(|_|"CLI peer registry unavailable")?;for tx in peers.values(){if let Err(error)=tx.try_send(Outbound{value:event.clone(),ack:None}){self.record_issue(format!("socket push not queued: {error}"))}}}match self.renderer_tx.lock(){Ok(guard)=>if let Some(tx)=guard.as_ref(){if let Err(error)=tx.try_send(Outbound{value:event,ack:None}){self.record_issue(format!("renderer push not queued: {error}"))}}else{self.record_issue("renderer already stopped".into())},Err(_)=>self.record_issue("renderer queue unavailable".into())}Ok(())}
}
struct HandshakeStream{inner:TcpStream,hub:Arc<Hub>,deadline:Option<Instant>}
impl io::Read for HandshakeStream{fn read(&mut self,buf:&mut[u8])->io::Result<usize>{if self.deadline.is_some_and(|d|Instant::now()>=d||self.hub.stopping.load(Ordering::Acquire)){return Err(io::Error::new(io::ErrorKind::TimedOut,"CLI handshake stopped or expired"))}self.inner.read(buf)}}
impl io::Write for HandshakeStream{fn write(&mut self,buf:&[u8])->io::Result<usize>{if self.deadline.is_some_and(|d|Instant::now()>=d||self.hub.stopping.load(Ordering::Acquire)){return Err(io::Error::new(io::ErrorKind::TimedOut,"CLI handshake stopped or expired"))}self.inner.write(buf)}fn flush(&mut self)->io::Result<()>{self.inner.flush()}}
pub fn serve_socket(stream:TcpStream,hub:Arc<Hub>)->Result<(),String>{
 stream.set_read_timeout(Some(Duration::from_millis(100))).map_err(|e|e.to_string())?;stream.set_write_timeout(Some(Duration::from_secs(2))).map_err(|e|e.to_string())?;
 let deadline=Instant::now()+Duration::from_secs(2);let stream=HandshakeStream{inner:stream,hub:hub.clone(),deadline:Some(deadline)};let mut handshake=tungstenite::accept_hdr(stream,|req:&tungstenite::handshake::server::Request,response:tungstenite::handshake::server::Response|{if req.uri().query().is_some_and(|q|q.split('&').any(|p|p=="process=cli")){Ok(response)}else{Err(tungstenite::handshake::server::ErrorResponse::new(Some("CLI endpoint required".into())))}});let mut socket=loop{match handshake{Ok(socket)=>break socket,Err(tungstenite::HandshakeError::Interrupted(pending))=>{if hub.stopping.load(Ordering::Acquire){return Ok(())}if Instant::now()>=deadline{return Err("CLI handshake timed out".into())}handshake=pending.handshake()},Err(tungstenite::HandshakeError::Failure(e))=>return Err(format!("CLI handshake failed: {e}"))}};
 socket.get_mut().deadline=None;
 let n=NEXT_ID.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|v|v.checked_add(1)).map_err(|_|"CLI identity space exhausted")?;let id=format!("cli-{n}");svc::cli_connected(&hub.state,&hub.order,&id)?;
 let(tx,rx)=mpsc::sync_channel::<Outbound>(64);let registered=hub.peers.lock().map_err(|_|"CLI peer registry unavailable").map(|mut peers|{peers.insert(id.clone(),tx.clone());});if let Err(error)=registered{let cleanup=svc::cli_disconnected(&hub.state,&hub.order,&id,&mut |e|hub.publish(e));return Err(format!("{error}; disconnect cleanup: {cleanup:?}"))}
 let cancel=Arc::new(AtomicBool::new(false));let mut jobs=Vec::<thread::JoinHandle<()>>::new();
 let result='outer: loop{
  if hub.stopping.load(Ordering::Acquire){break Ok(())}
  for _ in 0..16{let Ok(out)=rx.try_recv()else{break};let sent=socket.send(tungstenite::Message::Text(out.value.to_string().into())).map_err(|e|format!("CLI send failed: {e}"));if let Some(ack)=out.ack{let _=ack.try_send(sent.clone());}if let Err(e)=sent{hub.record_issue(e.clone());break 'outer Err(e)}}
  while let Some(i)=jobs.iter().position(|h|h.is_finished()){let job=jobs.swap_remove(i);if job.join().is_err(){break 'outer Err("CLI request worker panicked".into())}}
  match socket.read(){
   Ok(tungstenite::Message::Text(text))=>{let message:Value=match serde_json::from_str(&text){Ok(v)=>v,Err(_)=>continue};if message["name"]!="cli-add-demo-paths-to-analyses"{continue}let Some(uuid)=message["uuid"].as_str().map(str::to_owned)else{continue};if jobs.len()>=16{break Err("CLI request concurrency limit reached".into())}let payload=message.get("payload").cloned().unwrap_or(Value::Null);let h=hub.clone();let client=id.clone();let response=tx.clone();let stopped=cancel.clone();let spawn=thread::Builder::new().spawn(move||{let positions=payload.get("analyzePositions").and_then(Value::as_bool);let outcome=(h.prepare)(payload,&stopped).and_then(|(mut reply,demos)|{let (accepted,new_work)=svc::cli_enqueue(&h.state,&h.order,&client,demos,positions,||chrono::DateTime::<chrono::Utc>::from(std::time::SystemTime::now()).to_rfc3339_opts(chrono::SecondsFormat::Millis,true),&mut |e|h.publish(e))?;if accepted{if new_work{if let Err(e)=(h.wake)(){h.record_issue(format!("scheduler wake failed after enqueue: {e}"))}}}else{reply["addedDemos"]=json!([])}Ok(reply)});let value=match outcome{Ok(v)=>json!({"name":"reply","uuid":uuid,"payload":v}),Err(e)=>json!({"name":"reply-error","uuid":uuid,"payload":e})};if response.try_send(Outbound{value,ack:None}).is_err(){h.record_issue("CLI reply not queued; client may have disconnected".into())}});match spawn{Ok(job)=>jobs.push(job),Err(e)=>break Err(format!("CLI request spawn failed: {e}"))}},
   Ok(tungstenite::Message::Close(_))|Err(tungstenite::Error::ConnectionClosed|tungstenite::Error::AlreadyClosed)=>break Ok(()),
   Err(tungstenite::Error::Io(e)) if matches!(e.kind(),io::ErrorKind::WouldBlock|io::ErrorKind::TimedOut)=>{},Err(e)=>break Err(format!("CLI read failed: {e}")),_=>{}
  }
 };
 cancel.store(true,Ordering::Release);let mut cleanup=Vec::new();if let Ok(mut peers)=hub.peers.lock(){peers.remove(&id);}else{cleanup.push("peer registry cleanup failed".to_string())}let mut closed=false;for _ in 0..3{match svc::cli_disconnected(&hub.state,&hub.order,&id,&mut |e|hub.publish(e)){Ok(())=>{closed=true;break},Err(e)=>{cleanup.push(format!("disconnect: {e}"));thread::sleep(Duration::from_millis(50));}}}if let Err(e)=(hub.wake)(){cleanup.push(format!("scheduler reconciliation wake: {e}"))}
 let deadline=Instant::now()+Duration::from_secs(6);while jobs.iter().any(|h|!h.is_finished())&&Instant::now()<deadline{thread::sleep(Duration::from_millis(10))}let all_done=jobs.iter().all(|h|h.is_finished());for job in jobs{if job.is_finished(){if job.join().is_err(){cleanup.push("request worker panicked".into())}}else{match hub.request_workers.lock(){Ok(mut workers)=>workers.push(job),Err(_)=>cleanup.push("request worker tracking unavailable; shutdown unconfirmed".into())}}}let dropped=rx.try_iter().count();if dropped>0{hub.record_issue(format!("socket closed with {dropped} queued messages not sent"));}if !all_done{cleanup.push("request worker shutdown and late outbound delivery unconfirmed".into())}if closed&&all_done{if let Ok(mut s)=hub.state.lock(){s.forget_client(&id)}else{cleanup.push("session reap failed".into())}}
 if !cleanup.is_empty(){return Err(format!("socket result {result:?}; cleanup: {}",cleanup.join("; ")))}result
}
pub struct CliListener{hub:Arc<Hub>,worker:Option<thread::JoinHandle<Result<(),String>>>,terminal:Option<Result<(),String>>}
impl CliListener{
 pub fn start(listener:std::net::TcpListener,hub:Arc<Hub>,max:usize)->Result<Self,String>{if max==0||!listener.local_addr().map_err(|e|e.to_string())?.ip().is_loopback(){return Err("CLI listener requires loopback and positive connection capacity".into())}listener.set_nonblocking(true).map_err(|e|e.to_string())?;let h=hub.clone();let worker=thread::Builder::new().spawn(move||{let mut clients=Vec::<thread::JoinHandle<Result<(),String>>>::new();let mut errors=Vec::new();while !h.stopping.load(Ordering::Acquire){while let Some(i)=clients.iter().position(|j|j.is_finished()){match clients.swap_remove(i).join(){Ok(Ok(()))=>{},Ok(Err(e))=>errors.push(e),Err(_)=>errors.push("CLI socket worker panicked".into())}}match listener.accept(){Ok((stream,_))=>{if clients.len()>=max{drop(stream);errors.push("CLI connection capacity reached".into());continue}let h2=h.clone();match thread::Builder::new().spawn(move||serve_socket(stream,h2)){Ok(job)=>clients.push(job),Err(e)=>errors.push(format!("CLI socket spawn failed: {e}"))}},Err(e) if e.kind()==io::ErrorKind::WouldBlock=>thread::sleep(Duration::from_millis(10)),Err(e)=>{errors.push(format!("CLI accept failed: {e}"));break}}}drop(listener);for job in clients{match job.join(){Ok(Ok(()))=>{},Ok(Err(e))=>errors.push(e),Err(_)=>errors.push("CLI socket worker panicked".into())}}if errors.is_empty(){Ok(())}else{Err(errors.join("; "))}}).map_err(|e|format!("CLI listener spawn failed: {e}"))?;Ok(Self{hub,worker:Some(worker),terminal:None})}
 pub fn is_stopped(&self)->bool{self.worker.is_none()}
 pub fn shutdown(&mut self,timeout:Duration)->Result<(),String>{self.hub.stopping.store(true,Ordering::Release);let deadline=Instant::now()+timeout;while self.worker.as_ref().is_some_and(|w|!w.is_finished())&&Instant::now()<deadline{thread::sleep(Duration::from_millis(10))}if self.worker.as_ref().is_some_and(|w|!w.is_finished()){return Err("CLI listener shutdown unconfirmed".into())}if let Some(worker)=self.worker.take(){self.terminal=Some(worker.join().unwrap_or_else(|_|Err("CLI listener worker panicked".into())))}self.terminal.clone().unwrap_or(Ok(()))}
}
impl Drop for CliListener{fn drop(&mut self){self.hub.stopping.store(true,Ordering::Release)}}

#[cfg(test)] mod pg80_deadline_tests{use super::*;
 fn hub()->Hub{Hub::new(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_|Ok(vec![]))}
 #[test]fn renderer_shutdown_lock_contention_is_bounded_and_retryable(){let h=hub();let held=h.renderer_tx.lock().unwrap();let start=Instant::now();assert!(h.shutdown_renderer(Duration::from_millis(40)).unwrap_err().contains("unconfirmed"));assert!(start.elapsed()<Duration::from_secs(1));drop(held);h.shutdown_renderer(Duration::from_secs(1)).unwrap();}
 #[test]fn renderer_panic_is_latched_after_retry(){let h=Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),|_|panic!("renderer panic"));h.publish(json!({"name":"test"})).unwrap();let end=Instant::now()+Duration::from_secs(1);while !h.renderer_worker.lock().unwrap().as_ref().unwrap().is_finished(){assert!(Instant::now()<end);thread::yield_now();}assert!(h.shutdown_renderer(Duration::from_secs(1)).unwrap_err().contains("panicked"));assert!(h.shutdown_renderer(Duration::from_secs(1)).unwrap_err().contains("panicked"));}
 #[test]fn diagnostic_lock_contention_is_bounded(){let h=hub();let held=h.issues.lock().unwrap();let start=Instant::now();assert!(h.delivery_issues_until(Duration::from_millis(40)).unwrap_err().contains("unconfirmed"));assert!(start.elapsed()<Duration::from_secs(1));drop(held);h.shutdown_renderer(Duration::from_secs(1)).unwrap();}
 #[test]fn expired_shutdown_admission_does_not_claim_success(){let h=hub();assert!(h.stop_admission(Duration::ZERO).unwrap_err().contains("unconfirmed"));h.shutdown_renderer(Duration::from_secs(1)).unwrap();}
 #[test]fn settings_push_detects_disconnected_peer(){let h=hub();let(tx,rx)=mpsc::sync_channel(1);h.peers.lock().unwrap().insert("peer".into(),tx);drop(rx);assert!(h.publish_peers_confirmed(&json!({"name":"settings-updated"}),Duration::from_millis(100)).is_err());h.peers.lock().unwrap().clear();h.shutdown_renderer(Duration::from_secs(1)).unwrap();}

 #[test]fn settings_push_waits_for_socket_ack_and_bounds_missing_ack(){let h=hub();let(tx,rx)=mpsc::sync_channel(1);h.peers.lock().unwrap().insert("peer".into(),tx);let worker=thread::spawn(move||{let out=rx.recv().unwrap();assert_eq!(out.value["name"],"settings-updated");out.ack.unwrap().send(Ok(())).unwrap()});assert!(h.publish_peers_confirmed(&json!({"name":"settings-updated"}),Duration::from_secs(1)).is_ok());worker.join().unwrap();h.peers.lock().unwrap().clear();let(tx,rx)=mpsc::sync_channel(1);h.peers.lock().unwrap().insert("stalled".into(),tx);assert!(h.publish_peers_confirmed(&json!({"name":"settings-updated"}),Duration::from_millis(40)).unwrap_err().contains("unconfirmed"));drop(rx);h.peers.lock().unwrap().clear();h.shutdown_renderer(Duration::from_secs(1)).unwrap();}

 #[test] fn pg102_settings_queue_does_not_wait_for_renderer_and_tracks_shutdown(){let(start_tx,start_rx)=mpsc::sync_channel(1);let(release_tx,release_rx)=mpsc::sync_channel::<()>(1);let release=Mutex::new(release_rx);let h=Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),move|_|{start_tx.send(()).unwrap();release.lock().unwrap().recv().unwrap();Ok(())});let before=Instant::now();assert!(h.queue_settings(json!({"name":"settings-updated"}),Duration::from_millis(30)).unwrap_err().contains("unconfirmed"));assert!(before.elapsed()<Duration::from_millis(500));start_rx.recv_timeout(Duration::from_secs(1)).unwrap();assert!(h.shutdown_renderer(Duration::from_millis(30)).is_err());release_tx.send(()).unwrap();h.shutdown_renderer(Duration::from_secs(1)).unwrap();}
 #[test] fn pg102_peer_queue_failure_does_not_suppress_renderer(){let(tx,rx)=mpsc::sync_channel(1);let delivered=Arc::new(Mutex::new(Vec::new()));let sink=delivered.clone();let h=Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),move|v|{sink.lock().unwrap().push(v);Ok(())});h.peers.lock().unwrap().insert("bad".into(),tx);drop(rx);assert!(h.queue_settings(json!({"name":"settings-updated"}),Duration::from_secs(1)).is_err());h.peers.lock().unwrap().clear();h.shutdown_renderer(Duration::from_secs(1)).unwrap();assert_eq!(delivered.lock().unwrap().len(),1);}

 #[test] fn pg102_busy_peer_lock_does_not_suppress_renderer(){let delivered=Arc::new(Mutex::new(Vec::new()));let sink=delivered.clone();let h=Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),move|v|{sink.lock().unwrap().push(v);Ok(())});let held=h.peers.lock().unwrap();assert!(h.queue_settings(json!({"name":"settings-updated"}),Duration::from_millis(30)).is_err());drop(held);h.shutdown_renderer(Duration::from_secs(1)).unwrap();assert_eq!(delivered.lock().unwrap().len(),1);}

 #[test] fn pg103_settings_reply_waits_for_renderer_emit(){let(start_tx,start_rx)=mpsc::sync_channel(1);let(release_tx,release_rx)=mpsc::sync_channel::<()>(1);let release=Mutex::new(release_rx);let h=Arc::new(Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),move|_|{start_tx.send(()).unwrap();release.lock().unwrap().recv().unwrap();Ok(())}));let other=h.clone();let handle=thread::spawn(move||other.queue_settings(json!({"name":"settings-updated"}),Duration::from_secs(1)));start_rx.recv_timeout(Duration::from_secs(1)).unwrap();assert!(!handle.is_finished());release_tx.send(()).unwrap();assert!(handle.join().unwrap().is_ok());h.shutdown_renderer(Duration::from_secs(1)).unwrap();}
 #[test] fn pg103_settings_renderer_error_reported_and_latched(){let h=Hub::from_parts(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),|_,_|Err("unused".into()),||Ok(()),|_|Err("test failure".into()));assert!(h.queue_settings(json!({"name":"settings-updated"}),Duration::from_secs(1)).unwrap_err().contains("test failure"));h.shutdown_renderer(Duration::from_secs(1)).unwrap();assert_eq!(h.delivery_issues().unwrap().len(),1);}

}

